<script lang="ts">
 import {onMount} from 'svelte';import{resolve}from '$app/paths';import ActionIcon from '#lib/shared/ActionIcon.svelte';
 import{ceramicModels,ceramicTierNames,listedCeramicAddons,type CeramicCatalogPricing}from '#lib/shared/bookingCatalog.ts';
 import PowderBasePrices from './PowderBasePrices.svelte';import PowderColorEntries from './PowderColorEntries.svelte';import PowderBikeTiers from './PowderBikeTiers.svelte';import PowderExceptions from './PowderExceptions.svelte';
 import{cleanPowderModel,powderModelProblem}from './powder-model';import type{PowderModel}from './ui-catalog';
 type Powder={parts:Record<string,[number,number]>;wheelRates:Record<string,[number,number]>;prismatic:Record<string,number>;extras:Record<string,number>;largeSwingarm:[number,number]};
 type Config={ceramic:CeramicCatalogPricing;powder:Powder;powderModel?:PowderModel};
 const maxConfigChars=20000;const maxPhotoBytes=4*1024*1024;const photoTypes=['image/jpeg','image/png','image/webp'];
 let draft=$state<Config>();let revision=$state(0);let canEdit=$state(false);let loading=$state(true);let busy=$state(false);let message=$state('');let notice=$state('');let stale=$state(false);const attempts=new Map<string,string>();
 let savedIds=$state<string[]>([]);let pending=$state<Record<string,File>>({});let photoNotes=$state<Record<string,string>>({});let photoVersion=$state<Record<string,number>>({});
 const problem=$derived(draft?.powderModel?powderModelProblem(draft.powderModel):'');
 const tooBig=$derived(draft?JSON.stringify($state.snapshot(draft)).length>maxConfigChars:false);
 function failure(status:number,code:string|undefined,fallback:string){if(code==='22023')return 'Check the coating rates.';if(status===409||code==='40001')return 'Prices changed since you opened this page. Reload prices, then make your changes again.';if(status===403||code==='42501')return 'You do not have permission to change prices.';return fallback;}
 function rememberSaved(){savedIds=draft?.powderModel?.colorEntries.map((e)=>e.id)??[];}
 async function uploadPhoto(id:string,file:File){const note=(text:string)=>{photoNotes[id]=text;};if(!photoTypes.includes(file.type)){note('Choose a JPEG, PNG or WebP photo.');return false;}if(file.size>maxPhotoBytes){note('That photo is over 4 MB. Choose a smaller one.');return false;}
  note('Uploading photo…');try{const r=await fetch(resolve('/api/pricing/color-photo')+'?entry='+encodeURIComponent(id),{method:'PUT',headers:{'content-type':file.type},body:file});if(!r.ok)throw Error(r.status===403?'You do not have permission to upload photos.':(await r.json().catch(()=>null))?.message??'The photo could not be uploaded.');
  const entry=draft?.powderModel?.colorEntries.find((e)=>e.id===id);if(!entry)return false;entry.photoPath=(await r.json()).path;photoVersion[id]=(photoVersion[id]??0)+1;note('Photo uploaded. Save to publish it.');return true;}catch(e){note(e instanceof Error?e.message:'The photo could not be uploaded.');return false;}}
 async function pickPhoto(id:string,file:File){if(savedIds.includes(id)){await uploadPhoto(id,file);return;}pending[id]=file;photoNotes[id]='Save prices first. This photo uploads right after.';}
 async function sendPending(){const ids=Object.keys(pending).filter((id)=>savedIds.includes(id));let any=false;for(const id of ids){const file=pending[id];delete pending[id];if(await uploadPhoto(id,file))any=true;}return any;}
 const tiers=Object.keys(ceramicModels).map(Number) as (keyof typeof ceramicModels)[];
 async function load(){loading=true;message='';try{const r=await fetch(resolve('/api/pricing/catalog'));if(!r.ok)throw Error((await r.json()).message??'Could not load coating prices.');const data=await r.json();canEdit=data?.canEdit===true;revision=data?.revision??0;draft=data?.config?.ceramic?.tiers&&data?.config?.powder?.parts?data.config:undefined;stale=false;pending={};photoNotes={};rememberSaved();}catch(e){message=e instanceof Error?e.message:'Could not load coating prices.';}finally{loading=false;}}
 async function persist(){if(!draft)return false;const config=$state.snapshot(draft);if(config.powderModel)config.powderModel=cleanPowderModel(config.powderModel);const input={revision,config};const key=JSON.stringify(input);const requestId=attempts.get(key)??crypto.randomUUID();attempts.set(key,requestId);
  try{const r=await fetch(resolve('/api/pricing/catalog'),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({...input,requestId})});if(!r.ok){const body=await r.json().catch(()=>null);stale=r.status===409||body?.code==='40001';throw Error(failure(r.status,body?.code,body?.message??'Could not save coating prices.'));}revision=(await r.json()).revision;attempts.delete(key);rememberSaved();return true;}catch(e){message=e instanceof Error?e.message:'Could not save prices.';return false;}}
 async function save(e:SubmitEvent){e.preventDefault();if(!draft||busy||stale||problem||tooBig)return;busy=true;message=notice='';try{if(!await persist())return;notice='Coating prices saved. Existing bookings keep their quoted prices.';if(await sendPending()){if(await persist())notice='Coating prices and photos saved. Existing bookings keep their quoted prices.';else notice='';}}finally{busy=false;}}
 onMount(()=>{void load();});
</script>
{#if loading}<p role="status">Loading coating price catalog…</p>{:else if draft}
<form class="card stack" onsubmit={save}><h3>Ceramic coating prices</h3><p class="muted">Amounts are in Philippine pesos before discounts. Saved booking line items keep their quoted prices.</p><fieldset class="stack" disabled={!canEdit||busy||stale}><legend>Motorcycle tiers</legend><div class="cols">{#each tiers as tier(tier)}<label>{ceramicTierNames[tier]}<input type="number" min="0" max="21474836.47" step=".01" bind:value={draft.ceramic.tiers[tier]} required/></label>{/each}</div></fieldset><fieldset class="stack" disabled={!canEdit||busy||stale}><legend>Add-on prices</legend><p class="small muted">Matte to Glossy, Inner coating, and Graphene coating use these ranges when the motorcycle has no pricing tier.</p>{#each Object.keys(draft.ceramic.addons) as addon}{@const key=addon as keyof CeramicCatalogPricing['addons']}<div class="addon-row"><strong>{addon}</strong><label>Minimum<input aria-label={addon+' minimum price'} type="number" min="0" max="21474836.47" step=".01" bind:value={draft.ceramic.addons[key][0]} required/></label><label>Maximum<input aria-label={addon+' maximum price'} type="number" min={draft.ceramic.addons[key][0]} max="21474836.47" step=".01" bind:value={draft.ceramic.addons[key][1]} required/></label></div>{/each}</fieldset><fieldset class="stack" disabled={!canEdit||busy||stale}><legend>Add-on rates for priced tiers</legend><div class="cols">{#each listedCeramicAddons as addon}<label>{addon}<input type="number" min="0" max="21474836.47" step=".01" bind:value={draft.ceramic.listedAddons[addon]} required/></label>{/each}<label>Matte to Glossy · Premium tier or 2026 Honda PCX<input type="number" min="0" max="21474836.47" step=".01" bind:value={draft.ceramic.premiumGloss} required/></label></div></fieldset>
{#if draft.powderModel}<details open><summary>Powder wheel colours and sizes</summary><div class="stack"><PowderBasePrices bind:model={draft.powderModel} disabled={!canEdit||busy||stale}/><PowderColorEntries bind:model={draft.powderModel} bind:pending {savedIds} {photoNotes} {photoVersion} onphoto={pickPhoto} disabled={!canEdit||busy||stale}/><PowderBikeTiers bind:model={draft.powderModel} disabled={!canEdit||busy||stale}/><PowderExceptions bind:model={draft.powderModel} disabled={!canEdit||busy||stale}/></div></details>{/if}
<details><summary>Powder coating prices</summary><div class="stack"><fieldset class="stack" disabled={!canEdit||busy||stale}><legend>Parts</legend>{#each Object.keys(draft.powder.parts) as part}<div class="addon-row"><strong>{part}</strong><label>Minimum<input type="number" min="0" max="21474836.47" step=".01" bind:value={draft.powder.parts[part][0]} required/></label><label>Maximum<input type="number" min={draft.powder.parts[part][0]} max="21474836.47" step=".01" bind:value={draft.powder.parts[part][1]} required/></label></div>{/each}</fieldset><fieldset class="stack" disabled={!canEdit||busy||stale}><legend>Wheel categories</legend>{#each Object.keys(draft.powder.wheelRates) as wheel}<div class="addon-row"><strong>{wheel}</strong><label>Minimum<input type="number" min="0" max="21474836.47" step=".01" bind:value={draft.powder.wheelRates[wheel][0]} required/></label><label>Maximum<input type="number" min={draft.powder.wheelRates[wheel][0]} max="21474836.47" step=".01" bind:value={draft.powder.wheelRates[wheel][1]} required/></label></div>{/each}</fieldset><fieldset class="stack" disabled={!canEdit||busy||stale}><legend>Prismatic finishes and wheel extras</legend><div class="cols">{#each Object.keys(draft.powder.prismatic) as key}<label>Prismatic · {key}<input type="number" min="0" max="21474836.47" step=".01" bind:value={draft.powder.prismatic[key]} required/></label>{/each}{#each Object.keys(draft.powder.extras) as key}<label>{key}<input type="number" min="0" max="21474836.47" step=".01" bind:value={draft.powder.extras[key]} required/></label>{/each}<label>Large swingarm minimum<input type="number" min="0" max="21474836.47" step=".01" bind:value={draft.powder.largeSwingarm[0]} required/></label><label>Large swingarm maximum<input type="number" min={draft.powder.largeSwingarm[0]} max="21474836.47" step=".01" bind:value={draft.powder.largeSwingarm[1]} required/></label></div></fieldset></div></details>
{#if problem}<p role="alert">{problem}</p>{/if}{#if tooBig}<p role="alert">The price list is too large to save. Remove colours or exceptions you no longer use.</p>{/if}{#if message}<p role="alert">{message}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}<div class="row">{#if canEdit}<button class="btn" disabled={busy||stale||!!problem||tooBig}><ActionIcon name="save"/>Save coating prices</button>{/if}<button class="btn ghost" type="button" onclick={load} disabled={busy}>Reload prices</button></div></form>
{:else}<section class="card stack"><h3>Coating price catalog</h3><p>No rates are configured yet. Ask the Owner to configure the price catalog before accepting quoted bookings.</p>{#if message}<p role="alert">{message}</p>{/if}<button class="btn sm ghost" onclick={load}>Reload prices</button></section>{/if}
<style>fieldset{min-inline-size:0;border:1px solid var(--line);border-radius:.4rem;padding:.8rem}legend{padding-inline:.4rem;font-weight:700}.addon-row{display:grid;grid-template-columns:minmax(0,2fr) repeat(2,minmax(0,1fr));gap:.6rem;align-items:center}details>div{padding-top:.75rem}@media(max-width:560px){.addon-row{grid-template-columns:repeat(2,minmax(0,1fr))}.addon-row strong{grid-column:1/-1}}</style>
